do $$ begin if exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='is_platform_owner' and pg_get_function_identity_arguments(p.oid)='') and not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='is_platform_owner_session' and pg_get_function_identity_arguments(p.oid)='') then alter function public.is_platform_owner() rename to is_platform_owner_session; end if; end $$; create or replace function public.is_platform_owner_session() returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and (coalesce(p.is_admin,false) or lower(coalesce(p.role::text,'')) in ('owner','platform_admin','super_admin','admin'))); $$; grant execute on function public.is_platform_owner_session() to authenticated; revoke execute on function public.is_platform_owner_session() from anon; create or replace function public.business_can_manage(p_business_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.is_platform_owner_session() or exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role::text) in ('owner','admin','manager')); $$; create or replace function public.business_admin_guard(p_business_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.is_platform_owner_session() or exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role::text) in ('owner','admin')); $$; create or replace function public.fleet_actor_is_manager(p_business_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.is_platform_owner_session() or exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role::text) in ('owner','admin','manager')); $$; grant execute on function public.fleet_actor_is_manager(uuid) to authenticated; revoke execute on function public.fleet_actor_is_manager(uuid) from anon;
